        {
            return Err(Error::ReadbackRequired);
        }
        Ok(())
    }

    pub(crate) fn respond(
        &self,
        operation: OriginalVersionLocalReadOperationV1,
        bytes: &[u8],
        request_id: u64,
    ) -> Result<Vec<u8>, Error> {
