pub struct OriginalCircuitLearningReadOwnerV1<C: AnchorWitnessStore, S: AnchorWitnessStore> {
    cell: PublishedCircuitCellOwnerV1<C>,
    source: CircuitTaskSourceReadbackV1<S>,
    identity: AgentdIdentity,
    context: ReadProfile,
    binding: Digest32,
