            }
        };
        self.require_task_input_current()?;
        if cell.read_learning_selection(&coordinator)? != selection {
            return Err(Error::Binding("original selection changed during read"));
        }
        self.require_task_input_current()?;
        Ok(Readback {
            observation,
            publication,
            source_input,
            source_publication,
        })
    }
}

